cd /app && python3 << 'EOF'
import pandas as pd

df = pd.read_csv('benchmark/data.csv')

# Let's create the chart data as JSON for embedding in HTML
import json

# 1. Listings per city
listings = df['city'].value_counts().sort_index().to_dict()

# 2. Median price by city (only cities with price data)
price_medians = {}
for city in df['city'].unique():
    city_prices = df[(df['city'] == city) & (df['price'].notna())]['price']
    if len(city_prices) > 0:
        price_medians[city] = round(city_prices.median(), 2)
    else:
        price_medians[city] = None

# 3. Mean price by city
price_means = {}
for city in df['city'].unique():
    city_prices = df[(df['city'] == city) & (df['price'].notna())]['price']
    if len(city_prices) > 0:
        price_means[city] = round(city_prices.mean(), 2)
    else:
        price_means[city] = None

# 4. Room type breakdown
room_types = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
room_type_data = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    total = len(city_df)
    room_type_data[city] = {}
    for rt in room_types:
        count = (city_df['room_type'] == rt).sum()
        pct = round(count / total * 100, 1)
        room_type_data[city][rt] = {'count': count, 'pct': pct}

# 5. Professional host share
pro_share = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    pro = (city_df['calculated_host_listings_count'] >= 5).sum()
    pct = round(pro / len(city_df) * 100, 1)
    pro_share[city] = pct

# 6. Reviews per month mean
rpm_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    rpm = city_df['reviews_per_month'].mean()
    rpm_mean[city] = round(rpm, 2)

# 7. Availability mean
avail_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    avail = city_df['availability_365'].mean()
    avail_mean[city] = round(avail, 1)

# 8. Entire home share
entire_share = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    entire = (city_df['room_type'] == 'Entire home/apt').sum()
    pct = round(entire / len(city_df) * 100, 1)
    entire_share[city] = pct

# 9. Price by room type
price_by_room = {}
for city in sorted(df['city'].unique()):
    price_by_room[city] = {}
    for rt in room_types:
        city_rt = df[(df['city'] == city) & (df['room_type'] == rt) & (df['price'].notna())]['price']
        if len(city_rt) > 0:
            price_by_room[city][rt] = {
                'median': round(city_rt.median(), 2),
                'mean': round(city_rt.mean(), 2),
                'count': len(city_rt)
            }
        else:
            price_by_room[city][rt] = None

# 10. Minimum nights stats
min_nights_stats = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    min_nights_stats[city] = {
        'mean': round(city_df['minimum_nights'].mean(), 1),
        'median': int(city_df['minimum_nights'].median()),
        'pct_ge_30': round((city_df['minimum_nights'] >= 30).sum() / len(city_df) * 100, 1)
    }

# 11. Number of reviews LTM mean
reviews_ltm_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    reviews_ltm_mean[city] = round(city_df['number_of_reviews_ltm'].mean(), 2)

# 12. Host concentration (listings per host)
host_conc = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    host_conc[city] = {
        'mean_listings_per_host': round(city_df['calculated_host_listings_count'].mean(), 1),
        'median_listings_per_host': int(city_df['calculated_host_listings_count'].median()),
        'max_listings': int(city_df['calculated_host_listings_count'].max()),
        'pct_single_listing': round((city_df['calculated_host_listings_count'] == 1).sum() / len(city_df) * 100, 1)
    }

chart_data = {
    'listings': listings,
    'price_medians': price_medians,
    'price_means': price_means,
    'room_type_data': room_type_data,
    'pro_share': pro_share,
    'rpm_mean': rpm_mean,
    'avail_mean': avail_mean,
    'entire_share': entire_share,
    'price_by_room': price_by_room,
    'min_nights_stats': min_nights_stats,
    'reviews_ltm_mean': reviews_ltm_mean,
    'host_conc': host_conc
}

print(json.dumps(chart_data, indent=2))
EOF

cd /app && python3 << 'EOF'
import pandas as pd
import json

df = pd.read_csv('benchmark/data.csv')

def to_native(val):
    if pd.isna(val):
        return None
    if isinstance(val, (int, float)):
        return val
    return val

# 1. Listings per city
listings = {k: int(v) for k, v in df['city'].value_counts().sort_index().items()}

# 2. Median price by city
price_medians = {}
for city in sorted(df['city'].unique()):
    city_prices = df[(df['city'] == city) & (df['price'].notna())]['price']
    price_medians[city] = round(float(city_prices.median()), 2) if len(city_prices) > 0 else None

# 3. Mean price by city
price_means = {}
for city in sorted(df['city'].unique()):
    city_prices = df[(df['city'] == city) & (df['price'].notna())]['price']
    price_means[city] = round(float(city_prices.mean()), 2) if len(city_prices) > 0 else None

# 4. Room type breakdown
room_types = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
room_type_data = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    total = len(city_df)
    room_type_data[city] = {}
    for rt in room_types:
        count = int((city_df['room_type'] == rt).sum())
        pct = round(count / total * 100, 1)
        room_type_data[city][rt] = {'count': count, 'pct': pct}

# 5. Professional host share
pro_share = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    pro = int((city_df['calculated_host_listings_count'] >= 5).sum())
    pct = round(pro / len(city_df) * 100, 1)
    pro_share[city] = pct

# 6. Reviews per month mean
rpm_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    rpm_mean[city] = round(float(city_df['reviews_per_month'].mean()), 2)

# 7. Availability mean
avail_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    avail_mean[city] = round(float(city_df['availability_365'].mean()), 1)

# 8. Entire home share
entire_share = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    entire = int((city_df['room_type'] == 'Entire home/apt').sum())
    pct = round(entire / len(city_df) * 100, 1)
    entire_share[city] = pct

# 9. Price by room type
price_by_room = {}
for city in sorted(df['city'].unique()):
    price_by_room[city] = {}
    for rt in room_types:
        city_rt = df[(df['city'] == city) & (df['room_type'] == rt) & (df['price'].notna())]['price']
        if len(city_rt) > 0:
            price_by_room[city][rt] = {
                'median': round(float(city_rt.median()), 2),
                'mean': round(float(city_rt.mean()), 2),
                'count': int(len(city_rt))
            }
        else:
            price_by_room[city][rt] = None

# 10. Minimum nights stats
min_nights_stats = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    min_nights_stats[city] = {
        'mean': round(float(city_df['minimum_nights'].mean()), 1),
        'median': int(city_df['minimum_nights'].median()),
        'pct_ge_30': round(int((city_df['minimum_nights'] >= 30).sum()) / len(city_df) * 100, 1)
    }

# 11. Number of reviews LTM mean
reviews_ltm_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    reviews_ltm_mean[city] = round(float(city_df['number_of_reviews_ltm'].mean()), 2)

# 12. Host concentration
host_conc = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    host_conc[city] = {
        'mean_listings_per_host': round(float(city_df['calculated_host_listings_count'].mean()), 1),
        'median_listings_per_host': int(city_df['calculated_host_listings_count'].median()),
        'max_listings': int(city_df['calculated_host_listings_count'].max()),
        'pct_single_listing': round(int((city_df['calculated_host_listings_count'] == 1).sum()) / len(city_df) * 100, 1)
    }

# 13. Price percentiles
price_percentiles = {}
for city in sorted(df['city'].unique()):
    city_prices = df[(df['city'] == city) & (df['price'].notna())]['price']
    if len(city_prices) > 0:
        price_percentiles[city] = {
            'p10': round(float(city_prices.quantile(0.1)), 2),
            'p25': round(float(city_prices.quantile(0.25)), 2),
            'p50': round(float(city_prices.quantile(0.5)), 2),
            'p75': round(float(city_prices.quantile(0.75)), 2),
            'p90': round(float(city_prices.quantile(0.9)), 2),
        }
    else:
        price_percentiles[city] = None

# 14. Active listings % (reviews_per_month > 0)
active_pct = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    active = int((city_df['reviews_per_month'] > 0).sum())
    active_pct[city] = round(active / len(city_df) * 100, 1)

# 15. Number of reviews mean
reviews_mean = {}
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    reviews_mean[city] = round(float(city_df['number_of_reviews'].mean()), 2)

chart_data = {
    'listings': listings,
    'price_medians': price_medians,
    'price_means': price_means,
    'room_type_data': room_type_data,
    'pro_share': pro_share,
    'rpm_mean': rpm_mean,
    'avail_mean': avail_mean,
    'entire_share': entire_share,
    'price_by_room': price_by_room,
    'min_nights_stats': min_nights_stats,
    'reviews_ltm_mean': reviews_ltm_mean,
    'host_conc': host_conc,
    'price_percentiles': price_percentiles,
    'active_pct': active_pct,
    'reviews_mean': reviews_mean
}

with open('/app/output/chart_data.json', 'w') as f:
    json.dump(chart_data, f, indent=2)

print("Chart data saved to /app/output/chart_data.json")
print(json.dumps(chart_data, indent=2))
EOF

