        <tr><td><strong>Bangkok</strong></td><td class="num">4,018</td><td class="num">$1,400</td><td class="num">$2,337</td><td class="num">$4,647</td><td class="num">$200</td><td class="num">$102,858</td><td class="num">1.99</td></tr>
        <tr><td><strong>Barcelona</strong></td><td class="num">2,558</td><td class="num">$132</td><td class="num">$190</td><td class="num">$436</td><td class="num">$13</td><td class="num">$9,286</td><td class="num">2.30</td></tr>
        <tr><td><strong>London</strong></td><td class="num">10,800</td><td class="num">$135</td><td class="num">$210</td><td class="num">$536</td><td class="num">$10</td><td class="num">$28,000</td><td class="num">2.55</td></tr>
